class ChatAdministratorRights(TelegramObject, kw_only=True):
    """Represents the rights of an administrator in a chat.

    Attributes:
        is_anonymous: True, if the user's presence in the chat is hidden.
        can_manage_chat: True, if the administrator can access the chat event log, get boost list,
            see hidden supergroup and channel members, report spam messages, ignore slow mode, and
            send messages to the chat without paying Telegram Stars.
        can_delete_messages: True, if the administrator can delete messages of other users.
        can_manage_video_chats: True, if the administrator can manage video chats.
        can_restrict_members: True, if the administrator can restrict, ban or unban chat members, or
            access supergroup statistics.
        can_promote_members: True, if the administrator can add new administrators with a subset of
            their own privileges or demote administrators that they have promoted, directly or
            indirectly (promoted by administrators that were appointed by the user).
        can_change_info: True, if the user is allowed to change the chat title, photo and other
            settings.
        can_invite_users: True, if the user is allowed to invite new users to the chat.
        can_post_stories: True, if the administrator can post stories to the chat.
        can_edit_stories: True, if the administrator can edit stories posted by other users, post
            stories to the chat page, pin chat stories, and access the chat's story archive.
        can_delete_stories: True, if the administrator can delete stories posted by other users.
        can_post_messages (optional): Optional.
        can_edit_messages (optional): Optional.
        can_pin_messages (optional): Optional.
        can_manage_topics (optional): Optional.
        can_manage_direct_messages (optional): Optional.
        can_manage_tags (optional): Optional.
        can_send_welcome_messages: True, if the administrator can manage chat welcome messages or
            directly send them in the case of bots.

    Example::

        obj = ChatAdministratorRights(is_anonymous=True, can_manage_chat=True, can_delete_messages=True, can_manage_video_chats=True, can_restrict_members=True, can_promote_members=True, can_change_info=True, can_invite_users=True, can_post_stories=True, can_edit_stories=True, can_delete_stories=True, can_send_welcome_messages=True)
        obj.is_anonymous

    https://core.telegram.org/bots/api#chatadministratorrights
    """
    is_anonymous: bool = False
    can_manage_chat: bool = False
    can_delete_messages: bool = False
    can_manage_video_chats: bool = False
    can_restrict_members: bool = False
    can_promote_members: bool = False
    can_change_info: bool = False
    can_invite_users: bool = False
    can_post_stories: bool = False
    can_edit_stories: bool = False
    can_delete_stories: bool = False
    can_post_messages: bool | None = None
    can_edit_messages: bool | None = None
    can_pin_messages: bool | None = None
    can_manage_topics: bool | None = None
    can_manage_direct_messages: bool | None = None
    can_manage_tags: bool | None = None
    can_send_welcome_messages: bool = False

